package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.BeanProperty;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDateFormat;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen2Test {

    private TestDateTimeSerializer serializer;
    private SerializerProvider serializers;
    private BeanProperty property;
    private SerializationConfig config;
    private Class<Date> handledType = Date.class;

    // Concrete implementation for testing abstract class
    public static class TestDateTimeSerializer extends DateTimeSerializerBase<Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Class<Date> type, Boolean useTimestamp, DateFormat customFormat) {
            super(type, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean timestamp, DateFormat format) {
            return new TestDateTimeSerializer(handledType, timestamp, format);
        }

        @Override
        public void serialize(Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {
        }

        @Override
        public boolean isEmpty(SerializerProvider serializers, Date value) {
            return false;
        }

        @Override
        protected long _timestamp(Date value) {
            return value.getTime();
        }

        @Override
        public JsonNode getSchema(Type type, Type typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(JsonFormatVisitorWrapper visitor, JavaType typeHint) {
        }

        public Boolean getUseTimestamp() { return useTimestamp; }
        public DateFormat getCustomFormat() { return customFormat; }
    }

    @Before
    public void setUp() {
        serializer = new TestDateTimeSerializer(handledType, false, null);
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        config = mock(SerializationConfig.class);

        when(serializers.getConfig()).thenReturn(config);
        when(serializers.getLocale()).thenReturn(Locale.US);
        when(serializers.getTimeZone()).thenReturn(TimeZone.getTimeZone("UTC"));
    }

    @Test
    public void testCreateContextual_PropertyNull() throws JsonMappingException {
        JsonSerializer<?> result = serializer.createContextual(serializers, null);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NoFormatOverrides() throws JsonMappingException {
        // Mock findFormatOverrides to return null via a spy or by ensuring no annotations are found
        // Since findFormatOverrides is protected and part of the logic, we simulate via the property
        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(null).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        assertSame(spySerializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        assertTrue(result instanceof TestDateTimeSerializer);
        assertTrue(((TestDateTimeSerializer) result).getUseTimestamp());
    }

    @Test
    public void testCreateContextual_WithPattern() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(true);
        when(formatValue.getPattern()).thenReturn("yyyy-MM-dd");
        when(formatValue.hasLocale()).thenReturn(true);
        when(formatValue.getLocale()).thenReturn(Locale.FRANCE);
        when(formatValue.hasTimeZone()).thenReturn(true);
        when(formatValue.getTimeZone()).thenReturn(TimeZone.getTimeZone("GMT"));

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        TestDateTimeSerializer res = (TestDateTimeSerializer) result;
        assertTrue(res.getCustomFormat() instanceof SimpleDateFormat);
        SimpleDateFormat sdf = (SimpleDateFormat) res.getCustomFormat();
        assertEquals("yyyy-MM-dd", sdf.toPattern());
        assertEquals(Locale.FRANCE, sdf.getLocale());
        assertEquals("GMT", sdf.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_WithPatternNoLocOrTZ() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(true);
        when(formatValue.getPattern()).thenReturn("yyyy");
        when(formatValue.hasLocale()).thenReturn(false);
        when(formatValue.hasTimeZone()).thenReturn(false);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        SimpleDateFormat sdf = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(Locale.US, sdf.getLocale());
        assertEquals("UTC", sdf.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_StdDateFormatWithLocaleAndTZ() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(false);
        when(formatValue.hasLocale()).thenReturn(true);
        when(formatValue.getLocale()).thenReturn(Locale.GERMANY);
        when(formatValue.hasTimeZone()).thenReturn(true);
        when(formatValue.getTimeZone()).thenReturn(TimeZone.getTimeZone("EST"));

        StdDateFormat stdDateFormat = new StdDateFormat();
        when(config.getDateFormat()).thenReturn(stdDateFormat);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        StdDateFormat res = (StdDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(Locale.GERMANY, res.getLocale());
        assertEquals("EST", res.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_NoChangesRequired() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING); // asString is true
        when(formatValue.hasPattern()).thenReturn(false);
        when(formatValue.hasLocale()).thenReturn(false);
        when(formatValue.hasTimeZone()).thenReturn(false);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        // If not StdDateFormat and not SimpleDateFormat (to trigger the "not usable" branch)
        // but wait, if !hasLocale && !hasTZ && !asString return this. 
        // Here asString is true, so it proceeds.
        // If df0 is not StdDateFormat and not SimpleDateFormat, it reports error.

        DateFormat badDf = mock(DateFormat.class);
        when(config.getDateFormat()).thenReturn(badDf);

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        // Since badDf is not StdDateFormat and not SimpleDateFormat, it should report error.
        // The method calls serializers.reportBadDefinition.
        verify(serializers).reportBadDefinition(eq(handledType), contains("not a `SimpleDateFormat`"));
    }

    @Test
    public void testCreateContextual_SimpleDateFormatWithLocale() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(false);
        when(formatValue.hasLocale()).thenReturn(true);
        when(formatValue.getLocale()).thenReturn(Locale.JAPAN);
        when(formatValue.hasTimeZone()).thenReturn(false);

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        when(config.getDateFormat()).thenReturn(sdf);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(Locale.JAPAN, res.getLocale());
    }

    @Test
    public void testCreateContextual_SimpleDateFormatWithTimeZoneOnly() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(false);
        when(formatValue.hasLocale()).thenReturn(false);
        when(formatValue.hasTimeZone()).thenReturn(true);
        TimeZone newTz = TimeZone.getTimeZone("Asia/Tokyo");
        when(formatValue.getTimeZone()).thenReturn(newTz);

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
        when(config.getDateFormat()).thenReturn(sdf);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals("Asia/Tokyo", res.getTimeZone().getID());
    }

    @Test
    public void testCreateContextual_SimpleDateFormatCloneNoChange() throws JsonMappingException {
        JsonFormat.Value formatValue = mock(JsonFormat.Value.class);
        when(formatValue.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(formatValue.hasPattern()).thenReturn(false);
        when(formatValue.hasLocale()).thenReturn(false);
        when(formatValue.hasTimeZone()).thenReturn(false);

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy");
        when(config.getDateFormat()).thenReturn(sdf);

        TestDateTimeSerializer spySerializer = spy(serializer);
        doReturn(formatValue).when(spySerializer).findFormatOverrides(any(), any(), any());

        JsonSerializer<?> result = spySerializer.createContextual(serializers, property);
        SimpleDateFormat res = (SimpleDateFormat) ((TestDateTimeSerializer) result).getCustomFormat();
        assertEquals(sdf.toPattern(), res.toPattern());
        assertNotSame(sdf, res);
    }
}
